if ( $ean !== '' ) {
	global $wpdb;
	$e = (int) $wpdb->get_var( $wpdb->prepare(
		"SELECT post_id FROM {$wpdb->postmeta} WHERE meta_key IN ('_ean','_global_unique_id') AND meta_value=%s LIMIT 1", $ean ) );
	if ( $e ) { wp_send_json_error( 'toks EAN jau yra: #' . $e . ' ' . get_the_title( $e ) ); }
}

$kaina  = isset( $d['kaina'] ) ? self::skaicius( $d['kaina'] ) : 0;
/* v1.4: aprasymas ateina SEKCIJOMIS ir surenkamas i ta pacia HTML
   struktura, kokia ateina is importo — kitaip prekes puslapyje
   lentyneliu nebutu, o pilnumas rodytu „be sudeties". */
$sek = ( isset( $d['sekcijos'] ) && is_array( $d['sekcijos'] ) ) ? $d['sekcijos'] : array();
$sek_sw = array();
foreach ( $sek as $k => $v ) {
	$k = sanitize_text_field( (string) $k );
	$v = trim( (string) $v );
	if ( $k !== '' && $v !== '' ) { $sek_sw[ $k ] = $v; }
}
$apras = $sek_sw ? self::sekcijos_html( $sek_sw )
	: ( isset( $d['aprasymas'] ) ? wp_kses_post( $d['aprasymas'] ) : '' );
$katid  = isset( $d['kategorija'] ) ? (int) $d['kategorija'] : 0;
$svoris = isset( $d['svoris'] ) ? self::skaicius( $d['svoris'] ) : 0;
$foto   = isset( $d['foto'] ) ? (int) $d['foto'] : 0;

/* v1.8: kopijos laukai. Kategoriju gali buti kelios — prekes vieta
   kataloge yra jos dalis, o viena issaugota kategorija reikstu, kad
   kopija dingsta is puses sarasu, kuriuose originalas matomas. */
$katai = array();
foreach ( (array) ( $d['kategorijos'] ?? array() ) as $k ) {
	$k = (int) $k;
	if ( $k && get_term( $k, 'product_cat' ) && ! is_wp_error( get_term( $k, 'product_cat' ) ) ) { $katai[] = $k; }
}
if ( $katid && ! in_array( $katid, $katai, true ) ) { $katai[] = $katid; }

$trumpas  = isset( $d['trumpas'] ) ? wp_kses_post( $d['trumpas'] ) : '';
$matmenys = is_array( $d['matmenys'] ?? null ) ? $d['matmenys'] : array();
$galerija = array_values( array_filter( array_map( 'intval', (array) ( $d['galerija'] ?? array() ) ) ) );

$prod = new WC_Product_Simple();
$prod->set_name( $pav );
$prod->set_sku( $sku );
$prod->set_status( 'draft' );          /* busena sprendziama zemiau */
$prod->set_catalog_visibility( 'visible' );
$prod->set_manage_stock( false );      /* likuti valdo partijos (FEFO) */
/* PVM: naujos prekes VISADA `taxable`. S654 pamoka — penki importo
   profiliai buvo palike `none`, ir 988 prekes checkout'e ejo be PVM. */
$prod->set_tax_status( 'taxable' );
if ( $kaina > 0 ) { $prod->set_regular_price( (string) $kaina ); }
if ( $apras !== '' ) { $prod->set_description( $apras ); }
if ( $trumpas !== '' ) { $prod->set_short_description( $trumpas ); }
if ( $svoris > 0 ) { $prod->set_weight( (string) $svoris ); }
foreach ( array( 'ilgis' => 'set_length', 'plotis' => 'set_width', 'aukstis' => 'set_height' ) as $r => $m ) {
	$v = isset( $matmenys[ $r ] ) ? self::skaicius( $matmenys[ $r ] ) : 0;
	if ( $v > 0 ) { $prod->{$m}( (string) $v ); }
}
if ( $katai ) { $prod->set_category_ids( $katai ); }
if ( $galerija ) { $prod->set_gallery_image_ids( $galerija ); }
$pid = $prod->save();

if ( ! $pid ) { wp_send_json_error( 'nepavyko sukurti prekės' ); }

/* AV sandelis — be sios zymes preke neatsirastu nei partijose, nei
   savo eilese, o gavimas butu beprasmis. */
update_post_meta( $pid, '_ps_sandelis', 'AV' );
if ( $ean !== '' ) {
	update_post_meta( $pid, '_ean', $ean );
	update_post_meta( $pid, '_global_unique_id', $ean );
}
if ( $foto > 0 && get_post_type( $foto ) === 'attachment' ) { set_post_thumbnail( $pid, $foto ); }

/* Taksonomijos — TIK per term_id (slug kolizija: „1,5 kg" ir „15 kg"
   sanitizuojasi i ta pati „15-kg"). */
$tax_map = array(
	'brendas'       => 'product_brand',
	'gyvuno_rusis'  => 'pa_gyvuno_rusis',
	'pakuotes_dydis'=> 'pa_pakuotes_dydis',
);
foreach ( $tax_map as $raktas => $tax ) {
	$tid = isset( $d[ $raktas ] ) ? (int) $d[ $raktas ] : 0;
	if ( ! $tid || ! taxonomy_exists( $tax ) ) { continue; }
	$t = get_term( $tid );
	if ( ! $t || is_wp_error( $t ) || $t->taxonomy !== $tax ) { continue; }
	wp_set_object_terms( $pid, array( $tid ), $tax, false );
	if ( strpos( $tax, 'pa_' ) === 0 ) {
		/* Taksonominis atributas neissilaiko be registracijos
		   `_product_attributes` — WC naktį nusalintu orphan rysius. */
		$reg = get_post_meta( $pid, '_product_attributes', true );
		if ( ! is_array( $reg ) ) { $reg = array(); }
		$reg[ $tax ] = array( 'name' => $tax, 'value' => '', 'position' => count( $reg ),
			'is_visible' => 1, 'is_variation' => 0, 'is_taxonomy' => 1 );
